(function (window, document, $) {
    "use strict";

    function Typed(element, options) {
        var self = this;

        this.el = element;
        this.options = {};

        // Copy default options
        Object.keys(defaults).forEach(function (key) {
            self.options[key] = defaults[key];
        });

        // Override with user options
        Object.keys(options).forEach(function (key) {
            self.options[key] = options[key];
        });

        this.isInput =
            this.el.tagName.toLowerCase() === "input";

        this.attr = this.options.attr;
        this.showCursor =
            !this.isInput && this.options.showCursor;

        this.elContent = this.attr
            ? this.el.getAttribute(this.attr)
            : this.el.textContent;

        this.contentType = this.options.contentType;
        this.typeSpeed = this.options.typeSpeed;
        this.startDelay = this.options.startDelay;
        this.backSpeed = this.options.backSpeed;
        this.backDelay = this.options.backDelay;

        this.fadeOut = this.options.fadeOut;
        this.fadeOutClass = this.options.fadeOutClass;
        this.fadeOutDelay = this.options.fadeOutDelay;

        if ($ && this.options.stringsElement instanceof $) {
            this.stringsElement = this.options.stringsElement[0];
        } else {
            this.stringsElement = this.options.stringsElement;
        }

        this.strings = this.options.strings;

        this.strPos = 0;
        this.arrayPos = 0;
        this.stopNum = 0;

        this.loop = this.options.loop;
        this.loopCount = this.options.loopCount;
        this.curLoop = 0;

        this.stop = false;

        this.cursorChar = this.options.cursorChar;
        this.shuffle = this.options.shuffle;
        this.sequence = [];

        this.build();
    }

    Typed.prototype = {

        constructor: Typed,

        init: function () {
            var self = this;

            self.timeout = setTimeout(function () {

                for (var i = 0; i < self.strings.length; i++) {
                    self.sequence[i] = i;
                }

                if (self.shuffle) {
                    self.sequence = self.shuffleArray(self.sequence);
                }

                self.typewrite(
                    self.strings[self.sequence[self.arrayPos]],
                    self.strPos
                );

            }, self.startDelay);
        },

        build: function () {

            var self = this;

            if (this.showCursor) {

                this.cursor = document.createElement("span");
                this.cursor.className = "typed-cursor";
                this.cursor.innerHTML = this.cursorChar;

                if (this.el.parentNode) {
                    this.el.parentNode.insertBefore(
                        this.cursor,
                        this.el.nextSibling
                    );
                }
            }

            if (this.stringsElement) {

                this.strings = [];
                this.stringsElement.style.display = "none";

                Array.prototype.slice
                    .apply(this.stringsElement.children)
                    .forEach(function (child) {
                        self.strings.push(child.innerHTML);
                    });
            }

            this.init();
        },

        replaceText: function (text) {

            if (this.attr) {
                this.el.setAttribute(this.attr, text);
            } else if (this.isInput) {
                this.el.value = text;
            } else if (this.contentType === "html") {
                this.el.innerHTML = text;
            } else {
                this.el.textContent = text;
            }
        },

        shuffleArray: function (array) {

            var current = array.length;
            var temp, random;

            while (--current) {

                random = Math.floor(Math.random() * (current + 1));

                temp = array[random];
                array[random] = array[current];
                array[current] = temp;
            }

            return array;
        },

        reset: function () {

            clearInterval(this.timeout);

            this.el.textContent = "";

            if (
                this.cursor &&
                this.cursor.parentNode
            ) {
                this.cursor.parentNode.removeChild(this.cursor);
            }

            this.strPos = 0;
            this.arrayPos = 0;
            this.curLoop = 0;

            this.options.resetCallback();
        }
        
    };

    Typed.new = function (selector, option) {

        var elements = Array.prototype.slice.apply(
            document.querySelectorAll(selector)
        );

        elements.forEach(function (element) {

            var typed = element._typed;
            var options =
                typeof option === "object" && option;

            if (typed) {
                typed.reset();
            }

            element._typed = typed =
                new Typed(element, options);

            if (typeof option === "string") {
                typed[option]();
            }
        });
    };

    if ($) {

        $.fn.typed = function (option) {

            return this.each(function () {

                var $this = $(this);

                var typed = $this.data("typed");
                var options =
                    typeof option === "object" && option;

                if (typed) {
                    typed.reset();
                }

                $this.data(
                    "typed",
                    typed = new Typed(this, options)
                );

                if (typeof option === "string") {
                    typed[option]();
                }
            });
        };
    }

    window.Typed = Typed;

    var defaults = {

        strings: [
            "My First Bootstrap Page",
            "Resize this responsive page to see the effect!"
        ],

        stringsElement: null,

        typeSpeed: 0,
        startDelay: 0,
        backSpeed: 0,
        backDelay: 500,

        shuffle: false,

        fadeOut: false,
        fadeOutClass: "typed-fade-out",
        fadeOutDelay: 500,

        loop: false,
        loopCount: false,

        showCursor: true,
        cursorChar: "|",

        attr: null,

        contentType: "html",

        callback: function () { },
        preStringTyped: function () { },
        onStringTyped: function () { },
        resetCallback: function () { }
    };

})(window, document, window.jQuery);